  function renderInsights(){const set=(id,v)=>{if($(id))$(id).textContent=v};const sent=batches.reduce((n,b)=>n+Number(b.sent||0),0),replied=batches.reduce((n,b)=>n+Number(b.replied||0),0),positive=batches.reduce((n,b)=>n+Number(b.positive||0),0),confirmed=creators.filter(c=>c.status==="已合作").length,published=creators.filter(c=>["已发布","已完成"].includes(c.deliveryStatus)).length,reviewed=creators.filter(c=>Number.isFinite(Number(c.contentScore))).length,quality=creators.filter(c=>Number(c.contentScore)>=4).length,deliveryRate=confirmed?Math.round(published/confirmed*100)+"%":"—";set("insightReplyRate",sent?Math.round(replied/sent*100)+"%":"—");set("insightPositiveRate",replied?Math.round(positive/replied*100)+"%":"—");set("insightDeliveryRate",deliveryRate);set("dashboardDeliveryRate",deliveryRate);set("insightQualityRate",reviewed?Math.round(quality/reviewed*100)+"%":"—");const chart=$("batchEffectChart");if(chart)chart.innerHTML=batches.length?batches.slice(0,6).map(b=>{const total=Math.max(Number(b.creators||0),Number(b.sent||0),1),reach=Math.min(100,Math.round(Number(b.sent||0)/total*100)),yes=Math.min(reach,Math.round(Number(b.positive||0)/total*100));return '<div class="batch-chart-row"><span>'+escapeHtml(b.name)+'</span><div class="batch-chart-bars"><i style="width:'+reach+'%"></i><i style="width:'+yes+'%"></i></div><b>'+yes+'%</b></div>'}).join(""):'<div class="empty-state">创建建联批次并更新触达数据后，会显示效果对比。</div>'}
