  function syncCreatorCounts(){const total=creators.length,high=creators.filter(c=>scoreFor(c)>=85).length;["creatorTotalStat","libraryTotalStat","funnelCreatorTotal","currentCreatorCount","libraryCreatorCount"].forEach(id=>{if($(id))$(id).textContent=formatNum(total)});["highMatchStat","libraryHighStat"].forEach(id=>{if($(id))$(id).textContent=formatNum(high)});if($("libraryPartnersStat"))$("libraryPartnersStat").textContent=creators.filter(c=>c.status==="已合作").length;if($("libraryAttentionStat"))$("libraryAttentionStat").textContent=creators.filter(c=>["待复核","黑名单"].includes(c.status)).length}
