  function formatNum(n){return n>=1000?(n/1000).toFixed(n%1000===0?0:1)+"k":String(n)}
  function scoreFor(c){
    const product=$("productCategory").value,goal=$("campaignGoal").value;
    let score=c.score+(c.category===product?7:-5);
    if(goal==="sales")score+=Math.round(c.audience/28)+Math.round(c.engagement/4);
    if(goal==="awareness")score+=Math.round(c.views/14000)+Math.round(c.audience/35);
    if(goal==="ugc")score+=(c.tags.some(t=>/演示|测评|技巧|食谱/.test(t))?6:0)+(c.contact.includes("未")?0:3);
    const feedback=feedbackById[c.id];
    if(feedback==="适合当前产品")score+=3;
    if(feedback==="品类不匹配")score-=14;
    if(feedback==="受众地区不匹配")score-=10;
    if(feedback==="内容质量不合适")score-=8;
    if(feedback==="费用不合适")score-=5;
    return Math.max(40,Math.min(99,score));
  }
