  function parseCsv(text){
    text=String(text||"").replace(/^\uFEFF/,"");const first=(text.split(/\r?\n/,1)[0]||"");const delimiter=(first.match(/;/g)||[]).length>(first.match(/,/g)||[]).length?";":",";const rows=[];let row=[],cell="",quoted=false;
    for(let i=0;i<text.length;i++){const ch=text[i],next=text[i+1];if(ch==='"'&&quoted&&next==='"'){cell+='"';i++}else if(ch==='"'){quoted=!quoted}else if(ch===delimiter&&!quoted){row.push(cell);cell=""}else if((ch==="\n"||ch==="\r")&&!quoted){if(ch==="\r"&&next==="\n")i++;row.push(cell);if(row.some(v=>v.trim()))rows.push(row);row=[];cell=""}else cell+=ch}row.push(cell);if(row.some(v=>v.trim()))rows.push(row);
    if(!rows.length)return[];const normalize=v=>v.trim().toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-z0-9\u4e00-\u9fa5]/g,"");const firstCells=rows[0].map(normalize);const headerNames=["handle","username","tiktokhandle","账号","用户名","达人账号","tiktok用户名"];const hasHeader=firstCells.some(v=>headerNames.includes(v));let headers=hasHeader?firstCells:null;
    const data=hasHeader?rows.slice(1):rows;return data.map(values=>{const record={};if(headers){headers.forEach((h,i)=>record[h]=values[i]||"")}else record.handle=values[0]||"";return record}).filter(r=>Object.values(r).some(v=>String(v).trim()));
  }
  function field(row,names){for(const n of names){if(row[n]!==undefined&&String(row[n]).trim())return String(row[n]).trim()}return ""}
  function csvNumber(raw,fallback=0){let value=String(raw||"").replace(/[%\s]/g,"");const comma=value.lastIndexOf(","),dot=value.lastIndexOf(".");if(comma>=0&&dot>=0){value=comma>dot?value.replace(/\./g,"").replace(",","."):value.replace(/,/g,"")}else if(comma>=0){value=/,\d{1,2}$/.test(value)?value.replace(",","."):value.replace(/,/g,"")}else if(dot>=0&&/\.\d{3}(?:\.\d{3})+$/.test(value)){value=value.replace(/\./g,"")}else if(dot>=0&&/\.\d{3}$/.test(value)){value=value.replace(/\./g,"")}const n=Number(value);return Number.isFinite(n)?n:fallback}
  function importedCreator(row,index){const handle=field(row,["handle","username","tiktokhandle","账号","用户名","达人账号","tiktok用户名","tiktok"]);if(!handle)return null;const name=field(row,["name","fullname","姓名","名称"])||handle.replace(/^@/,"");const categoryRaw=field(row,["category","niche","内容方向","品类","分类"]).toLowerCase();let category="food",categoryName="食品饮料";if(/beauty|personal|美妆|个护/.test(categoryRaw)){category="beauty";categoryName="个护美妆"}else if(/home|clean|家清|家居/.test(categoryRaw)){category="home";categoryName="家清家居"}else if(/family|baby|母婴|家庭/.test(categoryRaw)){category="family";categoryName="母婴家庭"}else if(/pet|宠物/.test(categoryRaw)){category="pet";categoryName="宠物用品"}else if(categoryRaw){categoryName=field(row,["category","niche","内容方向","品类","分类"])}const city=field(row,["city","cidade","城市"]),state=field(row,["state","uf","州"]);return{id:Date.now()+index,name,handle:handle.startsWith("@")?handle:"@"+handle,initial:name.split(/\s+/).slice(0,2).map(x=>x[0]).join("").toUpperCase(),avatar:"",city:city||"待补充",state:state.toUpperCase(),language:field(row,["language","idioma","语言"])||"PT-BR",category,categoryName,followers:csvNumber(field(row,["followers","seguidores","粉丝数","粉丝"])),views:csvNumber(field(row,["views","medianviews","播放量","中位播放"])),engagement:csvNumber(field(row,["engagement","engagementrate","互动率"])),audience:csvNumber(field(row,["brazilaudience","brazilpercent","巴西受众","巴西受众占比"])),score:50,confidence:"低",status:"待复核",offer:[],tags:field(row,["tags","标签"]).split(/[;|，,]/).map(x=>x.trim()).filter(Boolean),reason:"导入资料待人工复核。",evidence:"由 CSV 导入，需补充来源和核验时间。",review:"未合作",contact:field(row,["contact","email","whatsapp","联系方式","商务邮箱"]),posts:0,active:new Date().toLocaleDateString("zh-CN")}}
  function openImportModal(){
    pendingCsvRows=[];openModal("导入达人 CSV",'<div class="notice">必需字段为 TikTok handle。支持中英文列名；可选姓名、城市、州、品类、语言、粉丝数、播放量、互动率、巴西受众占比、联系信息和标签。重复 handle 会跳过。</div><div class="field"><label>CSV 文件（UTF-8）</label><input type="file" id="modalCsv" accept=".csv,.txt,text/csv"></div><div id="importStatus" class="muted">请选择文件以预览导入行数。</div>',"导入后保存在当前浏览器，不会上传到服务器。","导入达人",()=>{const incoming=pendingCsvRows.map(importedCreator).filter(Boolean);const existing=new Set(creators.map(c=>String(c.handle||"").toLowerCase()));const fresh=incoming.filter(c=>{const k=c.handle.toLowerCase();if(existing.has(k))return false;existing.add(k);return true});creators.push(...fresh);persistState().then(ok=>{if(ok){renderCreators();renderLibrary();renderDashboard();showToast('已导入 '+fresh.length+' 位达人，跳过 '+(incoming.length-fresh.length)+' 条重复记录')} });closeModal()});
    const input=$("modalCsv");input.addEventListener("change",()=>{const file=input.files&&input.files[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{pendingCsvRows=parseCsv(reader.result);const preview=pendingCsvRows.slice(0,3).map(r=>field(r,["handle","username","tiktokhandle","账号","用户名"])||Object.values(r)[0]).filter(Boolean).join("、");$("importStatus").textContent='识别到 '+pendingCsvRows.length+' 行，预览：'+(preview||'未识别 handle 列，请检查表头。')};reader.onerror=()=>$("importStatus").textContent="文件读取失败，请另存为 UTF-8 CSV 后重试。";reader.readAsText(file,"UTF-8")});
  }
