  ["creatorSearch","categoryFilter","stateFilter","viewRange","scoreRange","brazilAudience","ptLanguage","excludeContacted","offerFit","sortSelect","campaignGoal"].forEach(id=>$(id).addEventListener("input",()=>{if(id==="viewRange")$("viewRangeLabel").textContent="≥ "+formatNum(Number($("viewRange").value));if(id==="scoreRange")$("scoreRangeLabel").textContent=$("scoreRange").value+" 分";if(id==="campaignGoal")updateGoal($("campaignGoal").value);else renderCreators()}));
