  $("addCreatorBtn").addEventListener("click",()=>openCreatorEditor());$("loadDemoBtn").addEventListener("click",loadDemoData);$("clearDemoBtn").addEventListener("click",clearDemoData);$("backupDataBtn").addEventListener("click",exportBackup);$("exportCreatorsBtn").addEventListener("click",exportCreatorsCsv);$("restoreBackupBtn").addEventListener("click",()=>$("jsonInput").click());
  $("exportInsightsBtn").addEventListener("click",exportInsightsCsv);
