  $("librarySearch").addEventListener("input",renderLibrary);$("libraryStatus").addEventListener("change",renderLibrary);$("libraryCategory").addEventListener("change",renderLibrary);
  $("libraryRows").addEventListener("click",e=>{const button=e.target.closest("[data-edit-creator]");if(button)openCreatorEditor(button.dataset.editCreator)});
  $("batchRows").addEventListener("change",e=>{const control=e.target.closest("[data-batch-index]");if(!control)return;const batch=batches[Number(control.dataset.batchIndex)];if(!batch)return;if(control.dataset.batchField){const field=control.dataset.batchField;batch[field]=Math.max(0,Math.min(Number(control.max)||Infinity,Number(control.value)||0));if(field==="sent"){batch.replied=Math.min(Number(batch.replied)||0,batch.sent);batch.positive=Math.min(Number(batch.positive)||0,batch.replied)}if(field==="replied")batch.positive=Math.min(Number(batch.positive)||0,batch.replied)}else batch.status=control.value;persistState().then(ok=>{if(ok){renderBatches();renderDashboard();showToast(control.dataset.batchField?"批次触达数据已保存":"批次状态已更新")}})});
  $("fulfillmentBoard").addEventListener("change",e=>{const select=e.target.closest("[data-delivery-id]");if(!select)return;const c=creators.find(x=>String(x.id)===String(select.dataset.deliveryId));if(!c)return;c.deliveryStatus=select.value;persistState().then(ok=>{if(ok){renderDashboard();renderReviewItems();showToast("履约阶段已更新")}})});
  $("taskList").addEventListener("click",e=>{const done=e.target.closest("[data-task-done]"),remove=e.target.closest("[data-task-delete]");if(done){const task=tasks.find(t=>String(t.id)===String(done.dataset.taskDone));if(task)task.done=true}else if(remove){tasks=tasks.filter(t=>String(t.id)!==String(remove.dataset.taskDelete))}else return;persistState().then(ok=>{if(ok){renderTasks();showToast(done?"任务已完成":"任务已删除")}})});
  $("librarySelectAll").addEventListener("change",e=>document.querySelectorAll("#libraryRows input[type=checkbox]").forEach(x=>x.checked=e.target.checked));
  $("refreshBatches").addEventListener("click",()=>{renderBatches();showToast("批次列表已刷新")});
